INSERT INTO products (id, name, slug, description, short_desc, price, compare_price, stock_qty, category_id, benefits, application_rate, gst_hsn, gst_rate, images, status) VALUES
  ('b1111111-1111-1111-1111-111111111111', 'RhizoBoost Pro', 'rhizoboost-pro', 'Advanced mycorrhizal inoculant containing Glomus intraradices and Glomus mosseae. Enhances root architecture and phosphorus uptake by 40%. Suitable for all crop types.', 'Mycorrhizal inoculant for 40% better phosphorus uptake', 450.00, 600.00, 150, 'a1111111-1111-1111-1111-111111111111', ARRAY['Enhances root growth', 'Improves phosphorus uptake', 'Drought tolerance', 'All crop types'], '2 kg per acre, mix with irrigation water', '3105', 18.00, '["https://images.unsplash.com/photo-1574943320219-553eb213f72d?w=600"]', 'active'),
  ('b2222222-2222-2222-2222-222222222222', 'SoilRevive 500', 'soilrevive-500', 'Concentrated Bacillus subtilis formulation with 500 million CFU/g. Rebuilds soil microbiome diversity and suppresses soil-borne pathogens naturally.', 'Bacillus subtilis concentrate for soil microbiome restoration', 380.00, 500.00, 200, 'a1111111-1111-1111-1111-111111111111', ARRAY['Restores soil microbiome', 'Suppresses pathogens', 'Improves soil structure', 'Organic certified'], '1 kg per acre, apply before sowing', '3105', 18.00, '["https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=600"]', 'active'),
  ('b3333333-3333-3333-3333-333333333333', 'NitroFix Max', 'nitrofix-max', 'Azotobacter chroococcum + Azospirillum brasilense dual strain nitrogen fixer. Converts atmospheric nitrogen to plant-available form, reducing chemical fertilizer need by 30%.', 'Dual-strain nitrogen fixer reducing fertilizer need by 30%', 320.00, 420.00, 180, 'a1111111-1111-1111-1111-111111111111', ARRAY['Fixes atmospheric nitrogen', 'Reduces fertilizer cost', 'Dual strain formula', 'Safe for all soils'], '500 ml per acre, foliar spray or soil drench', '3105', 18.00, '["https://images.unsplash.com/photo-1530836369250-ef72a3f5cda8?w=600"]', 'active'),
  ('b4444444-4444-4444-4444-444444444444', 'NeemGuard Elite', 'neemguard-elite', 'Cold-pressed neem oil emulsion with Azadirachtin content of 1500 ppm. Effective against 200+ pest species. Systemic action protects for 14-21 days.', 'Cold-pressed neem oil with 1500 ppm Azadirachtin', 280.00, 350.00, 250, 'a2222222-2222-2222-2222-222222222222', ARRAY['Controls 200+ pests', '14-21 day protection', 'Organic approved', 'No residue'], '2 ml per liter water, spray every 15 days', '3002', 12.00, '["https://images.unsplash.com/photo-1416879595882-3373a0480b5b?w=600"]', 'active'),
  ('b5555555-5555-5555-5555-555555555555', 'TrichoShield Plus', 'trichoshield-plus', 'Trichoderma viride + Trichoderma harzianum combination bio-fungicide. Colonizes root zone and outcompetes Fusarium, Rhizoctonia, and Pythium pathogens.', 'Trichoderma combination for root zone protection', 340.00, 450.00, 170, 'a2222222-2222-2222-2222-222222222222', ARRAY['Prevents root diseases', 'Outcompetes pathogens', 'Enhances nutrient uptake', 'Long-lasting'], '2 kg per acre, mix with FYM and apply to soil', '3105', 18.00, '["https://images.unsplash.com/photo-1592982537447-6f2a6a0c7c17?w=600"]', 'active'),
  ('b6666666-6666-6666-6666-666666666666', 'Beauveria Shield', 'beauveria-shield', 'Beauveria bassiana spore suspension (1×10^8 CFU/ml). Contact bio-insecticide targeting whitefly, aphids, thrips, and jassids. UV-stabilized formula.', 'Beauveria bassiana bio-insecticide for sucking pests', 420.00, 550.00, 120, 'a2222222-2222-2222-2222-222222222222', ARRAY['Targets sucking pests', 'UV-stabilized', 'No resistance buildup', 'Safe for beneficials'], '3 ml per liter, spray in evening hours', '3105', 18.00, '["https://images.unsplash.com/photo-1471193945509-9ad0617afabf?w=600"]', 'active'),
  ('b7777777-7777-7777-7777-777777777777', 'VermiGold Compost', 'vermigold-compost', 'Premium vermicompost from cow dung and agricultural waste. Rich in NPK, beneficial microbes, and humic acids. Produces earthworms for bait.', 'Premium vermicompost with humic acids', 180.00, 240.00, 300, 'a3333333-3333-3333-3333-333333333333', ARRAY['Rich in NPK', 'Beneficial microbes', 'Improves water retention', 'Produces earthworms'], '2-3 tonnes per acre, apply before last ploughing', '3101', 18.00, '["https://images.unsplash.com/photo-1585336261022-680e295ce3fe?w=600"]', 'active'),
  ('b8888888-8888-8888-8888-888888888888', 'BioGrow Granules', 'biogrow-granules', 'Multi-strain biofertilizer granules: PSB + KMB + Azotobacter + Lactic Acid Bacteria. Slow-release formula for sustained nutrient supply through the season.', 'Multi-strain slow-release biofertilizer granules', 290.00, 380.00, 220, 'a3333333-3333-3333-3333-333333333333', ARRAY['4 beneficial strains', 'Slow release formula', 'Season-long nutrition', 'Easy application'], '5 kg per acre, apply near root zone', '3105', 18.00, '["https://images.unsplash.com/photo-1556801712-76c8eb07af33?w=600"]', 'active'),
  ('b9999999-9999-9999-9999-999999999999', 'Humic Acid Plus', 'humic-acid-plus', 'Potassium humate solution (18% humic acid + 10% fulvic acid). Chelates micronutrients, improves soil CEC, and stimulates root development.', 'Humic + fulvic acid solution for soil CEC', 350.00, 450.00, 160, 'a3333333-3333-3333-3333-333333333333', ARRAY['Improves soil CEC', 'Chelates nutrients', 'Stimulates roots', 'Enhances fertilizer efficiency'], '1 liter per acre, mix with irrigation', '3105', 18.00, '["https://images.unsplash.com/photo-1589923188651-268a9765e432?w=600"]', 'active'),
  ('ba111111-1111-1111-1111-111111111111', 'Precision Soil Probe', 'precision-soil-probe', 'Stainless steel soil probe with depth markings (0-30cm). Ergonomic T-handle for easy sampling. Includes cleaning brush and carrying case.', 'Professional soil sampling probe kit', 1200.00, 1500.00, 50, 'a4444444-4444-4444-4444-444444444444', ARRAY['Stainless steel', 'Depth markings', 'Ergonomic handle', 'Carrying case included'], 'Push probe to desired depth, twist and pull', '9023', 18.00, '["https://images.unsplash.com/photo-1586771107445-d3ca888129ff?w=600"]', 'active'),
  ('ba222222-2222-2222-2222-222222222222', 'Digital pH Meter', 'digital-ph-meter', 'Handheld soil pH meter with LCD display. Measures pH 0-14 with ±0.1 accuracy. Waterproof IP65 rated. Battery included.', 'Portable soil pH meter with ±0.1 accuracy', 850.00, 1100.00, 75, 'a4444444-4444-4444-4444-444444444444', ARRAY['LCD display', '±0.1 accuracy', 'Waterproof IP65', 'Battery included'], 'Insert probe 5cm into moist soil, read LCD', '9023', 18.00, '["https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=600"]', 'active'),
  ('ba333333-3333-3333-3333-333333333333', 'Bio-Sprayer 16L', 'bio-sprayer-16l', '16-liter manual knapsack sprayer with brass nozzle set. Anti-drip mechanism, pressure gauge, and padded straps. Ideal for bio-pesticide application.', '16L manual sprayer with brass nozzles', 2400.00, 3000.00, 40, 'a4444444-4444-4444-4444-444444444444', ARRAY['16L capacity', 'Brass nozzles', 'Anti-drip mechanism', 'Padded straps'], 'Fill tank, pump to pressure, spray evenly', '8424', 18.00, '["https://images.unsplash.com/photo-1599057463025-23fa0f367e5a?w=600"]', 'active');
